public sealed record Customer(string Name, string? Email);

static string ContactLabel(Customer customer) => customer switch
{
    { Email: not null } => $"{customer.Name} <{customer.Email}>",
    { Name.Length: > 0 } => customer.Name,
    _ => "Unknown"
};

static string Classify(int[] values) => values switch
{
    [] => "empty",
    [var only] => $"single:{only}",
    [< 0, ..] => "starts-negative",
    [var first, .., var last] when first == last => "same-edges",
    _ => "other"
};
